      "comment" = "a proficiency check is rolled on 1d20 and compared to the character rating in the given proficiency: rolls LESS than the rating are successful - the strict inequality that distinguishes the proficiency check from the equal-or-less ability check.",
    }, {
      "name" = "dmvNoMagicAssumed",
      "value" = true,
      "comment" = "all of these rules assume the character uses no magical assistance; the effects of such devices, when used, always take precedence over a character innate swimming abilities.",
    }, {
      "name" = "dmvSwimProfRequiredAfloat",
      "value" = true,
      "comment" = "characters without swimming proficiency are unable to remain afloat in water and drown in deep water unless they are aided.",
    }, {
      "name" = "dmvBreathHeldWithoutProf",
      "value" = true,
      "comment" = "a character does not need swimming proficiency to be able to hold his breath.",
    }, {
      "name" = "dmvAnimalsSwimIfForced",
      "value" = true,
      "comment" = "almost all animals can swim, if forced to; wolves and other canines willingly follow prey into water, while most felines swim only in desperation.",
    }, {
      "name" = "dmvFireStoneNeverEnter",
      "value" = true,
      "comment" = "certain creatures - fire- and stone-based monsters in particular - never enter the water.",
    }, {
      "name" = "dmvEnduranceNeedsBreath",
      "value" = true,
      "comment" = "endurance reflects how long a character can continue swimming without resting, and assumes that he can breathe while swimming, i.e. is not swimming through a completely water-filled passage.",
    }, {
      "name" = "dmvEncCategoriesMatchPhb",
      "value" = true,
      "comment" = "the encumbrance categories match those described in the players handbook, page 101.",
    }, {
      "name" = "dmvEncumberedSinks",
      "value" = true,
      "comment" = "an encumbered character cannot move through the water under his own power; if he enters the water, he will sink (the Table 1 footnote).",
    }, {
      "name" = "dmvEnduranceLevelsPlusCon",
      "value" = true,
      "comment" = "a character swimming endurance is calculated by adding his total experience levels to his constitution score - the number of turns he can swim without rest.",
    }, {
      "name" = "dmvTreadingDoublesEndurance",
      "value" = true,
      "comment" = "a character who is only attempting to stay afloat by treading water doubles the number of turns of his swimming endurance.",
    }, {
      "name" = "dmvEndurOutMeansDrown",
      "value" = true,
      "comment" = "when a character runs out of endurance he will drown unless he can get out of deep water or find some means of staying afloat.",
    }, {
      "name" = "dmvHighSpeedDoublesRate",
      "value" = true,
      "comment" = "a character can elect to swim at high speed, doubling his rate of movement with the endurance penalty.",
    }, {
      "name" = "dmvHighSpeedRestEqual",
      "value" = true,
      "comment" = "immediately upon exiting the water, the high-speed swimmer must spend as much time resting as he spent swimming at high speed.",
    }, {
      "name" = "dmvStrBonusIsDamageBonus",
      "value" = true,
      "comment" = "the strength bonus added to swimming speed is the strength DAMAGE bonus (the strength-16 +1 example swims at 5 inches) - the DSG keys the speed bonus on the damage bonus where the WSG keyed it on strength bands; a pinned cross-book divergence, both cap at +3.",
    }, {
      "name" = "dmvDiveModifiedByEnc",
      "value" = true,
      "comment" = "the depth attainable on a diving round can be modified by encumbrance, as explained on Table 1.",
    }, {
      "name" = "dmvJumpBonusUnmodifiedByEnc",
      "value" = true,
      "comment" = "the additions for diving into water are not modified by encumbrance: a character jumping into the water can dive an extra 10 feet regardless of whether he is completely unencumbered or carrying heavy gear.",
    }, {
      "name" = "dmvSurfaceModifiedByEnc",
      "value" = true,
      "comment" = "the surfacing rate is modified by unusual encumbrance as shown on Table 1, and assumes the character is actively working to return to the surface.",
    }, {
      "name" = "dmvHeavyMustActivelySwim",
      "value" = true,
      "comment" = "a character encumbered with heavy gear or greater must actively swim for the surface, or he does not rise at all.",
    }, {
      "name" = "dmvIntentionalLoadingDmJudged",
      "value" = true,
      "comment" = "a character can intentionally load himself down (with rocks, etc.) to aid a dive and release the added weight when he wants to surface; the DM must decide how heavily the character must load himself to reach a certain encumbrance category.",
    }, {
      "name" = "dmvBreathRoundedUp",
      "value" = true,
      "comment" = "the breath durations and their halvings are all rounded up: the 1/3 constitution base, the strenuous halving and the no-breath halving.",
    }, {
      "name" = "dmvFullyEncumBreathBarred",
      "value" = true,
      "comment" = "a character cannot be fully encumbered while performing the nonstrenuous breath-holding functions (normal movement, searching for secret doors, picking a lock).",
    }, {
      "name" = "dmvStrenuousHalvesBreath",
      "value" = true,
      "comment" = "strenuous exercise (fighting, subduing, lifting or moving a heavy weight, moving at high speed) cuts the underwater time in half, rounded up - cumulative with the no-breath halving.",
    }, {
      "name" = "dmvFullyEncumAlwaysStrenuous",
      "value" = true,
      "comment" = "fully encumbered characters underwater are always considered to be performing strenuous exercise.",
    }, {
      "name" = "dmvNoDeepBreathHalves",
      "value" = true,
      "comment" = "a character without a chance to take a deep breath before submerging has his underwater time halved (rounded up), cumulative with the strenuous halving.",
    }, {
      "name" = "dmvConCheckAfterBreath",
      "value" = true,
      "comment" = "a character does not immediately die when his breath runs out: each round after, he makes the constitution check to stay alive with the -2 cumulative step.",
    }, {
      "name" = "dmvNonswimBreathPlusOne",
      "value" = true,
      "comment" = "holding breath in nonswimming situations (to avoid breathing the surrounding air) uses the swimming formula but adds one round.",
    }, {
      "name" = "dmvCantAvoidUnsuspectedGas",
      "value" = true,
      "comment" = "characters cannot use breath-holding to avoid the effects of a gas unless they suspect that a gas is about to be released.",
    }, {
      "name" = "dmvSpeedRelativeToWater",
      "value" = true,
      "comment" = "a character swimming speed is relative to the water he occupies: the stream carries him along at its speed plus or minus his swimming speed.",
    }, {
      "name" = "dmvRapidTransportUntilImpact",
      "value" = true,
      "comment" = "extremely rapid streams can move characters with enough momentum to do them considerable harm; until the character hits something, the water might prove a fast and direct form of transportation - submerged rocks and subterranean waterfalls change that impression quickly.",
    }, {
      "name" = "dmvWaterfallSaveVsBreath",
      "value" = true,
      "comment" = "a character carried over a waterfall receives half the normal damage for the distance of the fall, except that a saving throw vs. breath weapon is allowed, with the avoid-the-obstacles results.",
    }, {
      "name" = "dmvDangerRatingIsCadence",
      "value" = true,
      "comment" = "the stream danger rating tells how often a character must make a swimming proficiency check: the time between checks in rounds equals the rating - a stream rated one requires a check every round, one rated four every four rounds.",
    }, {
      "name" = "dmvLowRatingForcesHighSpeed",
      "value" = true,
      "comment" = "in a stream rated five or less, characters must swim at high speed.",
    }, {
      "name" = "dmvAllClassesLimitedClimb",
      "value" = true,
      "comment" = "members of all character classes have a limited ability to move up and down steep slopes, provided hand and footholds are available.",
    }, {
      "name" = "dmvOnlyThievesSheer",
      "value" = true,
      "comment" = "only thieves have the capability to ascend sheer walls, cliffs and the like.",
    }, {
      "name" = "dmvNonThiefRoughRoutes",
      "value" = true,
      "comment" = "other characters may try to climb very rough stone surfaces, as well as trees, poles, ropes and other simple routes.",
    }, {
      "name" = "dmvMountaineerBoosts",
      "value" = true,
      "comment" = "the mountaineering proficiency can increase climbing abilities for both thieves and non-thieves.",
    }, {
      "name" = "dmvThiefOnlySmoothTypes",
      "value" = true,
      "comment" = "walls that are very smooth, smooth with cracks, or rough can only be climbed by thieves, unless characters are using ropes, spikes or other tools.",
    }, {
      "name" = "dmvIceNeedsTools",
      "value" = true,
      "comment" = "ice walls can only be climbed by characters (including thieves) using tools.",
    }, {
      "name" = "dmvThiefOnlyRates",
      "value" = true,
      "comment" = "in all instances the Table 2 rates are for thieves only; all other characters move at half the thief rates.",
    }, {
      "name" = "dmvDexAdjAddsToRate",
      "value" = true,
      "comment" = "all characters can add their dexterity reaction/attacking adjustments to their rate of climbing.",
    }, {
      "name" = "dmvBarkNonslippery",
      "value" = true,
      "comment" = "any pole with tree bark still attached is considered a nonslippery surface.",
    }, {
      "name" = "dmvRopeOnlyUnbracedCat",
      "value" = true,
      "comment" = "a rope only falls into the pole category if the character cannot brace his feet against a wall or some other surface to aid the climb.",
    }, {
      "name" = "dmvSlopeSaveVsPetr",
      "value" = true,
      "comment" = "if a character falls while on a sloping wall surface, he can make a saving throw vs. petrification; if the save is successful, he takes no damage from the fall.",
    }, {
      "name" = "dmvNonslipperyDrySolid",
      "value" = true,
      "comment" = "nonslippery surfaces are dry and solid; they do not crumble when touched, and a character chance of falling is calculated at the normal rate.",
    }, {
      "name" = "dmvEncumbNoSheerWithoutTools",
      "value" = true,
      "comment" = "encumbered characters cannot climb sheer surfaces without the aid of tools.",
    }, {
      "name" = "dmvHeavyGearHalfRate",
      "value" = true,
      "comment" = "the heavy-gear and very-heavy-gear climbing halving is cumulative with all other effects.",
    }, {
      "name" = "dmvNormalGearFullRate",
      "value" = true,
      "comment" = "characters with no gear or normal gear can utilize the full climbing movement rates.",
    }, {
      "name" = "dmvNonThiefCheckEqualOrLess",
      "value" = true,
      "comment" = "the non-thief climbing check is rolled on 1d100 against the modified climbing rating: a result greater than the rating indicates failure, a result less than or equal to the rating means success.",
    }, {
      "name" = "dmvFailMeansNeverClimb",
      "value" = true,
      "comment" = "if a climbing check fails, the character can never climb that wall.",
    }, {
      "name" = "dmvFailCostsOneRound",
      "value" = true,
      "comment" = "even a failed climbing attempt requires one round of game time.",
    }, {
      "name" = "dmvNoPlateNoShield",
      "value" = true,
      "comment" = "characters cannot climb in any type of plate mail armor, nor can a shield be held by a climbing character.",
    }, {
      "name" = "dmvLeatherNoPenalty",
      "value" = true,
      "comment" = "leather armor does not penalize a climber.",
    }, {
      "name" = "dmvShieldSlungNoBenefit",
      "value" = true,
      "comment" = "a character can sling a shield over his shoulder to carry it along while climbing, but cannot receive any defensive benefit for a shield thus carried.",
    }, {
      "name" = "dmvSpikeShortensFall",
      "value" = true,
      "comment" = "the usual function of a spike is to shorten the distance a character falls: a spike 200 feet up a cliff with 50 feet of slack in the rope turns a fall beginning 50 feet higher into a 100-foot fall (50 down to the spike, 50 more of slack).",
    }, {
      "name" = "dmvUseMultipleSpikes",
      "value" = true,
      "comment" = "characters can help prevent spike-arrest accidents by using more than one spike.",
    }, {
      "name" = "dmvIceSpikeEachRound",
      "value" = true,
      "comment" = "climbing an ice wall absolutely requires spikes: a spike must be driven into the ice wall before a character can climb, the process must be repeated each round, and since it takes a round to drive a spike, the process is doubly slow.",
    }, {
      "name" = "dmvPoleWrapTechnique",
      "value" = true,
      "comment" = "a rope wrapped around a too-wide pole and pulled against as he climbs lets a character climb a pole whose diameter equals his own height; any pole wider than this should be treated as a wall.",
    }, {
      "name" = "dmvRappelFailFallsFull",
      "value" = true,
      "comment" = "a failed rappel climbing check means a fall from the top to the bottom of whatever distance is involved.",
    }, {
      "name" = "dmvRappelNormalRestrictions",
      "value" = true,
      "comment" = "all normal climbing restrictions (encumbrance, armor, etc.) apply to rappelling.",
    }, {
      "name" = "dmvAllClassesJump",
      "value" = true,
      "comment" = "characters of all classes have a limited ability to jump across obstacles, the same procedure as given for acrobats (unearthed arcana page 24).",
    }, {
      "name" = "dmvJumpOneSegment",
      "value" = true,
      "comment" = "all jumps require only one segment of time.",
    }, {
      "name" = "dmvNoBackwardOrExtended",
      "value" = true,
      "comment" = "unlike acrobats, other characters cannot attempt to jump backward or leap in an extended position.",
    }, {
      "name" = "dmvJumpNoNormalPenalty",
      "value" = true,
      "comment" = "unencumbered characters and characters carrying normal gear have no penalties to their jumping abilities - the encumbrance ladder starts at heavy gear.",
    }, {
      "name" = "dmvJumpNoRacialHumans",
      "value" = true,
      "comment" = "humans, elves and half-orcs suffer no racial penalty on a jump.",
    }, {
      "name" = "dmvFarSideAnchorProblem",
      "value" = true,
      "comment" = "the perennial rope problem is how to attach the rope to the far side: grapple-catchable irregularities are uncommon in a dungeon setting, more common in natural caves, and a once-bridged crossing invariably has wreckage of the bridge foundation to catch with a grappling hook.",
    }, {
      "name" = "dmvArrowRopeImpractical",
      "value" = true,
      "comment" = "the rope-tied-to-the-arrow trick is dashing and romantic but impractical: an arrow trailing a rope and fired into wood is simply not strong enough to support even the lightest of characters.",
    }, {
      "name" = "dmvRopeCrossCheckEachRound",
      "value" = true,
      "comment" = "a character crossing on such a line is in a precarious position indeed, and must make a climbing check each round that he is suspended.",
    }, {
      "name" = "dmvRopeCrossModsApply",
      "value" = true,
      "comment" = "on a rope crossing the modifiers for armor and encumbrance still apply to the climbing check.",
    }, {
      "name" = "dmvRopeAlwaysNonslippery",
      "value" = true,
      "comment" = "a rope is always considered a nonslippery surface.",
    }, {
      "name" = "dmvRopeWallRateApplies",
      "value" = true,
      "comment" = "the rate of climb listed for rope and wall applies to characters making a crossing on a rope.",
    }, {
      "name" = "dmvLoopThiefOrFamiliar",
      "value" = true,
      "comment" = "a thrown loop is a tricky maneuver that can only be attempted by thieves or other characters with a long and intimate familiarity with ropes (characters raised on farms, or who served as sailors).",
    }, {
      "name" = "dmvLoopRangeHalved",
      "value" = true,
      "comment" = "the thrown-loop range is halved if the character does not have the clear 10-foot radius around him to prepare the throw.",
    }, {
      "name" = "dmvLoopAttemptOneRound",
      "value" = true,
      "comment" = "a loop attempt takes one round; characters may make as many attempts as they wish, and the method carries the additional advantage of being virtually soundless.",
    }, {
      "name" = "dmvSwingPendulum",
      "value" = true,
      "comment" = "a rope supported at one end swings to a point where it is hanging straight down; a weight attached to the rope is carried past that point by momentum, creating the pendulum motion that gives characters problems when they ram into a solid object during their swing.",
    }, {
      "name" = "dmvSwingCheckToHold",
      "value" = true,
      "comment" = "if a character is holding a rope that swings into an obstacle, he must make an immediate climbing check to see if he can hold on; an unsuccessful check means he has been knocked off the rope and has fallen.",
    }, {
      "name" = "dmvSwingDropFractions",
      "value" = true,
      "comment" = "the swing damage drops all fractions: a character on a 15-foot rope receives no damage, and a character 35 feet down a rope suffers only 1d6 points of damage.",
    }, {
      "name" = "dmvAnyoneCanBelay",
      "value" = true,
      "comment" = "any character can attempt to protect another character against a fall with a belay; the only tool required is a rope, although spikes can add to the security of a belay.",
    }, {
      "name" = "dmvBelayRopeTied",
      "value" = true,
      "comment" = "the character to be protected must have a rope tied securely around him; the character performing the belay holds the other end of the rope, but does not tie it to himself.",
    }, {
      "name" = "dmvBelayPaysOutSlack",
      "value" = true,
      "comment" = "the belayer pays out the rope slowly as the protected character moves farther away from him; if the protected character should fall, the belayer grabs the rope tightly and braces himself to try to catch the shock of the weight.",
    }, {
      "name" = "dmvBelayCheckArrests",
      "value" = true,
      "comment" = "the belayer must roll a climbing check to arrest the fall: if successful, the rope is held and the other character can fall no farther than the length of the rope; if unsuccessful, the rope runs through the hands of the belayer too quickly and the fall proceeds normally.",
    }, {
      "name" = "dmvBelaySecondCheck",
      "value" = true,
      "comment" = "a belayer who successfully holds the rope but occupies a dangerous or narrow spot must make a second climbing check to maintain his hold on whatever surface he is clinging to; if the second check is unsuccessful, the belayer joins his companion in the fall.",
    }, {
      "name" = "dmvBelaySpikeAnchored",
      "value" = true,
      "comment" = "a belayer performing from a dangerous spot can use a spike to anchor himself: he performs the belay normally, and if he arrests the fall but fails his second check so that he is pulled into the fall, the spike should then catch both falling characters - with the standing 10 percent per supported character chance of pulling loose.",
    }, {
      "name" = "dmvBelayBothEndsNoChecks",
      "value" = true,
      "comment" = "a belay can hold one end of a rope used for support, as in a chasm crossing: with a grappling hook fastening the far side and a belay established on the near side, characters cross as if the rope were attached at both ends, and the character holding the rope makes no checks.",
    }, {
      "name" = "dmvRopedNoSingleFall",
      "value" = true,
      "comment" = "a party roped together insures that no single member will suffer a damaging fall; however, the group takes the risk of all members falling together.",
    }, {
      "name" = "dmvRopedSlowestRate",
      "value" = true,
      "comment" = "characters who are roped together must move at the rate of the slowest member, with the order of characters on the rope noted.",
    }, {
      "name" = "dmvRopedBothSidesCheck",
      "value" = true,
      "comment" = "if one roped character falls, the characters on each side of him must make climbing checks: if both checks are successful the fall is stopped immediately; if one character arrests the fall but the other fails, the -10 two-faller re-check follows.",
    }, {
      "name" = "dmvRopedCascadeRecheck",
      "value" = true,
      "comment" = "each time the weight of a new character is added to those who have fallen, the characters who have not fallen but are adjacent to those falling must make climbing checks; this continues until a successful climbing check is made on each side of the falling characters, or until the entire party falls.",
    }, {
      "name" = "dmvRopedEndSingleCheck",
      "value" = true,
      "comment" = "if a character or characters on the end of the rope fall, only the single character next to the falling character must make a check - it is more advantageous to have either the first or the last character fall, especially if the character next to him is a skilled climber.",
    } },
